'use strict';
/* MTG: decision workspace; private OpenAI key stays in Supabase Edge Function. */
const CONFIG=window.MTG_CONFIG||{};
const KEY='mtg-decision-workspace-v1';
const AREAS=[['quartiere','01','Quartiere','Aria, rumore, trasporti e servizi'],['condominio','02','Edificio e condominio','Parti comuni, spese e lavori'],['immobile','03','Immobile','Spazi, impianti, energia e documenti'],['acquisto','04','Prezzo e acquisto','Prezzo, costi e condizioni']];
const PREFS=[['prezzo','Prezzo'],['zona','Zona'],['spazi','Spazi'],['luminosita','Luminosità'],['tranquillita','Tranquillità'],['stato','Condizioni della casa']];
const DOCS=[['annuncio','Annuncio o brochure'],['planimetria','Planimetria catastale'],['ape','APE'],['visura','Visura catastale'],['edilizia','Pratiche edilizie'],['condominio','Verbali / spese condominiali'],['provenienza','Atto di provenienza'],['altro','Altro documento']];
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const now=()=>new Date().toISOString();
const uid=()=>crypto.randomUUID?crypto.randomUUID():'id_'+Date.now()+'_'+Math.random().toString(16).slice(2);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euros=n=>Number.isFinite(Number(n))&&Number(n)>0?new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)):'Non indicato';
const shortDate=x=>x?new Date(x).toLocaleDateString('it-IT'):'—';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function fresh(){return {version:1,profile:{budget:350000,location:'Milano',purpose:'primary',prefs:Object.fromEntries(PREFS.map(([k])=>[k,3])),custom:[]},homes:[],events:[],intents:[]}}
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'null')}}catch{state=fresh()}
let current=null,view='research',section='overview',expandedGap='',expertGap='',showAllGaps={},pendingGapDoc='',session=null,supa=null,syncTimer=null,cloudReady=false,cloudError='',busy=false;
function H(){return state.homes.find(h=>h.id===current)}
function log(type,properties={}){state.events.push({id:uid(),at:now(),type,...properties});if(state.events.length>1500)state.events=state.events.slice(-1500)}
function persist(){localStorage.setItem(KEY,JSON.stringify(state));scheduleSync()}
function scheduleSync(){if(!supa||!session||!cloudReady)return;clearTimeout(syncTimer);syncTimer=setTimeout(saveCloud,700)}
async function saveCloud(){if(!supa||!session||!cloudReady)return;const {error}=await supa.from('mtg_workspaces').upsert({user_id:session.user.id,data:state,updated_at:now()},{onConflict:'user_id'});if(error){cloudError=error.message;updateSyncLabel()}else{cloudError='';updateSyncLabel()}}
function updateSyncLabel(){const e=$('#syncLabel');if(e)e.textContent=!session?'Salvataggio locale nella sessione del browser · Accedi per sincronizzare i dati col tuo account':!cloudReady?'Salvataggio locale':cloudError?'Errore cloud: '+cloudError:'Sincronizzazione dati con account'}
function toast(message){const e=$('#toast');e.textContent=message;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',4200)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function render(){ $('#app').innerHTML=({research:researchPage,homes:homesPage,edit:createPage,property:propertyPage,compare:comparePage})[view]();$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view));$('#accountBtn').textContent=session?'Il mio account':'Accedi';updateSyncLabel();bind() }
function navigate(v,id){view=v;if(id)current=id;if(v==='property'&&!H()){view='homes'};render();scrollTo(0,0)}
function setSection(s){section=s;render();scrollTo(0,0)}
function isLegacyPreset(g){return ['quartiere_rumore','quartiere_aria','condominio_spese','immobile_planimetria','immobile_ape','acquisto_costi'].includes(g.id)&&(!g.history||g.history.length===0)&&!g.closed&&!g.answer&&!(g.documentIds||[]).length&&!(g.manualEvidence||[]).length}
function cleanupLegacyGaps(h){if(h?.gaps?.length){const prev=h.gaps.length;h.gaps=h.gaps.filter(g=>!isLegacyPreset(g));return prev-h.gaps.length}return 0}
// Semantic safeguards on top of the model prompt. The user content and close state always prevl.
const GAP_STOPWORDS=new Set('di del della delle degli dei e ed il lo la le gli un uno una per con sul sulla sulle nel nella nelle da a ad al alla alle che come cosa quale quali quando se sono stato stata avere ha hanno ci questo questa questi queste delle da fare verificare verifica richiedere chiedere ottenere sapere dati informazioni documento documenti immobile casa'.split(' '));
function gapTokens(g){const text=String((g.title||'')+' '+(g.reason||'')).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ');return new Set(text.split(/\s+/).filter(w=>w.length>3&&!GAP_STOPWORDS.has(w)).map(w=>w.slice(0,7)))}
function gapTheme(g){const t=(g.title+' '+(g.reason||'')).toLowerCase();const a=g.area||'';if(/rumor|acustic|insonorizz|traffico rumor/.test(t))return a+':rumore';if(/aria|inquinament|pm10|pm2|no2/.test(t))return a+':aria';if(/condomin|assemble|spes.+straordinar|lavori.+comun/.test(t))return a+':condominio_lavori';if(/planimetr|difformit|conformit.+catastal|distribuzione.+plan/.test(t))return a+':planimetria';if(/ape|classe energetic|certificazion.+energetic/.test(t))return a+':ape';if(/titol.+ediliz|pratic.+ediliz|ristrutturazion|cila|scia/.test(t))return a+':lavori_edilizi';if(/ipotec|pignorament|gravam/.test(t))return a+':gravami';if(/provenienz|titolar|proprietari/.test(t))return a+':provenienza';if(/mutuo|finanziament/.test(t))return a+':mutuo';if(/prezzo|costo totale|impost|mediazion|not|spese accessor/.test(t))return a+':costi';return ''}
function sameGap(a,b){if(a.area!==b.area)return false;if(a.id===b.id)return true;const ta=gapTheme(a),tb=gapTheme(b);if(ta&&ta===tb)return true;const aa=gapTokens(a),bb=gapTokens(b);const overlap=[...aa].filter(x=>bb.has(x)).length;return overlap>=2&&overlap/Math.min(Math.max(aa.size,1),Math.max(bb.size,1))>=0.7}
function distinctGaps(gaps){const out=[];for(const g of gaps){if(!g?.title||!g?.action||!g?.reason||!AREAS.some(a=>a[0]===g.area))continue;const n={...g,id:String(g.id||('gap_'+uid())).replace(/[^a-z0-9_]/gi,'').toLowerCase().slice(0,70)};if(!out.some(x=>sameGap(x,n)))out.push(n)}return out}
function createHome(){const h={id:uid(),name:'Nuovo immobile · '+shortDate(now()),description:'',link:'',address:'',price:null,sqm:null,floor:'',energy:'',condition:'',condoCosts:'',stage:'online',visited:false,visitedAt:null,visit:{feeling:null,light:null,quiet:null,layout:null,note:''},docs:[],gaps:[],analysis:null,Pros:[],Cons:[],customTopics:[],decision:{choice:'pending',reason:'',note:'',date:null},expertRequests:[],createdAt:now(),updatedAt:now()};state.homes.push(h);current=h.id;section='detls';log('home_created',{homeId:h.id});persist();navigate('property',h.id)}
function homeTitle(h){return h.name||`${h.condition||'Immobile'} · ${shortDate(h.createdAt)}`}
function suggestedHouseName(description,date){const match=String(description||'').match(/\b(monolocale|bilocale|trilocale|quadrilocale|attico|loft|villa|villetta|appartamento)\b/i);return (match?match[1].charAt(0).toUpperCase()+match[1].slice(1).toLowerCase():'Immobile')+' · '+shortDate(date)}
function pageTop(title,description,buttons=''){return `<div class="section-top"><div><div class="eyebrow">mindthegap. / La tua ricerca</div><h1>${title}</h1><p class="muted">${description}</p></div>${buttons}</div>`}
function researchPage(){const p=state.profile;return `${pageTop('Che cosa cerchi nella tua prossima casa?','Definisci una volta le tue priorità. Ogni casa sarà confrontata con gli stessi criteri, anche emotivi.','<div class="btn-row"><button class="btn outline" id="openHomes">Le mie case</button></div>')}<div class="split"><aside class="card sidebar"><div class="eyebrow">COME FUNZIONA</div><h3>Un percorso, più case</h3><p class="smalltext muted">1. Imposta le tue priorità<br>2. Aggiungi annunci e documenti<br>3. Valuta quartiere, condominio, casa e prezzo<br>4. Dopo la visita registra come ti sei sentito<br>5. Approfondisci gap e prendi una decisione</p><div class="rule"></div><span class="tiny" id="syncLabel"></span></aside><div class="mn-col"><form class="card stack" id="profileForm"><div class="form-grid"><div class="field"><label>Budget massimo (€)</label><input class="input" id="pBudget" type="number" min="0" value="${esc(p.budget)}"></div><div class="field"><label>Città o zona preferita</label><input class="input" id="pLocation" value="${esc(p.location)}"></div><div class="field"><label>Perché acquisti?</label><select class="input" id="pPurpose"><option value="primary" ${p.purpose==='primary'?'selected':''}>Abitazione principale</option><option value="upgrade" ${p.purpose==='upgrade'?'selected':''}>Cambio casa</option><option value="investment" ${p.purpose==='investment'?'selected':''}>Investimento</option><option value="other" ${p.purpose==='other'?'selected':''}>Altro</option></select></div></div><div class="rule"></div><h3>Quanto contano per te questi aspetti?</h3><p class="hint">1 = poco importante · 5 = decisivo. Il giudizio sulla singola casa sarà registrato separatamente.</p>${PREFS.map(([k,n])=>rangeRow(k,n,p.prefs[k]??3)).join('')}${p.custom.map(c=>rangeRow(c.id,c.name,c.weight)).join('')}<div class="form-grid"><div class="field"><label>Aggiungi un criterio personale</label><input class="input" id="customPref" maxlength="90" placeholder="Es. spazio per lavorare da casa"></div><div class="field"><label>&nbsp;</label><button type="button" class="btn outline" id="addPref">+ Aggiungi criterio</button></div></div><div class="btn-row"><button class="btn" type="submit">Salva le mie preferenze</button><button class="btn outline" type="button" id="startHome">+ Aggiungi un immobile</button></div></form></div></div>`}
function rangeRow(k,label,value){return `<div class="range-row"><label for="pref_${esc(k)}">${esc(label)}</label><input id="pref_${esc(k)}" type="range" min="1" max="5" value="${clamp(value,1,5)}" data-pref="${esc(k)}"><b class="right" data-weight-label="${esc(k)}">${value}/5</b></div>`}
function homesPage(){return `${pageTop('Le mie case','Puoi valutare più immobili in parallelo e tornare a una casa senza perdere informazioni.','<button class="btn" id="newHome">+ Aggiungi una casa</button>')}<div class="stack">${state.homes.length?state.homes.map(h=>`<div class="property-row"><div><div class="eyebrow">${esc(stageLabel(h.stage))} · ${shortDate(h.createdAt)}</div><h3>${esc(homeTitle(h))}</h3><p class="muted">${esc(h.address||'Indirizzo non specificato')} · ${euros(h.price)} · ${h.sqm?esc(h.sqm)+' m²':'Metratura non indicata'}</p><div class="taglist"><span>${h.docs.length} documenti</span><span>${h.gaps.filter(g=>!g.closed).length} questioni aperte</span><span>${h.visited?'Visita effettuata':'Non visitata'}</span></div></div><div class="btn-row"><button class="btn outline small" data-open="${h.id}">Apri</button><button class="btn ghost small" data-remove="${h.id}">Elimina</button></div></div>`).join(''):`<div class="card"><h2>Ancora nessun immobile</h2><p class="muted">Aggiungi il primo annuncio per avviare la valutazione.</p><button class="btn" id="firstHome">Aggiungi la prima casa</button></div>`}</div><p class="tiny mt" id="syncLabel"></p>`}
function createPage(){return '<div class="card">Crea prima un immobile dalla sezione “Le mie case”.</div>'}
function stageLabel(s){return ({online:'Vista online',visited:'Visitata',shortlist:'In shortlist',offer:'Valuto un’offerta',offered:'Offerta presentata',discarded:'Scartata'})[s]||'Vista online'}
function propertyPage(){const h=H();if(!h)return homesPage();const sections=[['detls','L’immobile'],['overview','Valutazione'],['visit','Dopo la visita'],['checks','Le verifiche'],['decision','Report e decisione']];return `<div class="section-top"><div><div class="eyebrow">LA MIA RICERCA / ${esc(homeTitle(h))}</div><h1>${esc(homeTitle(h))}</h1><p class="muted">${esc(h.address||'Indirizzo da definire')} · ${euros(h.price)} · ${h.sqm?esc(h.sqm)+' m²':'Superficie da indicare'}</p></div><div class="btn-row"><button class="btn outline small" id="editProfile">Modifica preferenze</button><button class="btn outline small" id="addNext">+ Nuova casa</button></div></div><div class="card mb"><div class="form-grid"><div class="field"><label>A che punto sei con questa casa?</label><select class="input" id="hStage">${['online','visited','shortlist','offer','offered','discarded'].map(s=>`<option value="${s}" ${h.stage===s?'selected':''}>${stageLabel(s)}</option>`).join('')}</select></div><div class="field"><label>Visita effettuata?</label><select class="input" id="hVisited"><option value="no" ${!h.visited?'selected':''}>Non ancora</option><option value="yes" ${h.visited?'selected':''}>Sì, ho visitato l’immobile</option></select></div></div></div><div class="stepper">${sections.map(([id,n],i)=>`<button class="${section===id?'active':''}" data-section="${id}">${i+1}. ${n}</button>`).join('')}</div>${({detls:detlsSection,overview:overviewSection,visit:visitSection,checks:checksSection,decision:decisionSection})[section](h)}<p class="tiny mt" id="syncLabel"></p>`}
function detlsSection(h){return `<div class="grid2"><form class="card stack" id="homeForm"><h2>Le informazioni dell’annuncio</h2><div class="field"><label>Nome della casa</label><input class="input" id="hName" value="${esc(h.name)}"></div><div class="field"><label>Descrizione dell’annuncio</label><textarea class="input" id="hDescription" rows="6" placeholder="Incolla qui la descrizione dell’annuncio">${esc(h.description)}</textarea></div><div class="form-grid"><div class="field"><label>Indirizzo o zona</label><input class="input" id="hAddress" value="${esc(h.address)}"></div><div class="field"><label>Link annuncio (Beta)</label><input class="input" id="hLink" type="url" placeholder="https://..." value="${esc(h.link)}"></div><div class="field"><label>Prezzo (€)</label><input class="input" type="number" id="hPrice" min="0" value="${esc(h.price||'')}"></div><div class="field"><label>Superficie (m²)</label><input class="input" type="number" id="hSqm" min="0" value="${esc(h.sqm||'')}"></div><div class="field"><label>Piano</label><input class="input" id="hFloor" value="${esc(h.floor)}"></div><div class="field"><label>Classe energetica dichiarata</label><select class="input" id="hEnergy"><option value="">Non dichiarata</option>${['A4','A3','A2','A1','B','C','D','E','F','G'].map(x=>`<option ${h.energy===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Condizioni</label><select class="input" id="hCondition"><option value="">Non dichiarate</option>${['Nuovo','Ristrutturato','Da ristrutturare','Buono stato'].map(x=>`<option ${h.condition===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Condominio €/mese (se noto)</label><input class="input" type="number" min="0" id="hCondo" value="${esc(h.condoCosts||'')}"></div></div><button class="btn" id="analyzeProperty" type="submit">${h.analysis?'Aggiorna analisi immobile':'Analizza immobile'} →</button><p class="tiny">Le informazioni saranno salvate automaticamente. Dopo l’analisi apriremo la valutazione completa (step 2). È necessario accedere per utilizzare MTG.</p></form><div class="stack"><div class="card stack"><h2>Hai già dei documenti?</h2><p class="muted smalltext">Carica i PDF testuali o TXT disponibili, anche dopo la visita. MTG registra il file e la data; la presenza del file non equivale a una verifica professionale.</p><div class="field"><label>Tipo di documento</label><select class="input" id="docKind">${DOCS.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></div><div class="field"><label>File PDF o TXT (max 8 MB)</label><input class="input" type="file" id="docFile" accept=".pdf,.txt,application/pdf,text/plain"></div><button class="btn outline" id="uploadDoc">+ Aggiungi documento</button><p class="tiny">I testi estratti sono salvati nel workspace; i PDF originali non vengono caricati su Supabase Storage in questa versione. Non usare dati di terzi sensibili senza autorizzazione.</p></div><div class="card stack"><h3>Documenti disponibili (${h.docs.length})</h3>${h.docs.map(d=>`<div class="property-row"><div><b class="smalltext">${esc(d.name)}</b><div class="tiny">${esc(DOCS.find(x=>x[0]===d.kind)?.[1]||'Documento')} · ${shortDate(d.addedAt)} · ${d.text?.length?'Testo leggibile':'Solo presenza dichiarata'}</div></div><button class="btn ghost small" data-del-doc="${d.id}">Rimuovi</button></div>`).join('')||'<p class="muted smalltext">Nessun documento caricato.</p>'}</div><p class="tiny">Carica eventuali documenti prima di premere «Analizza immobile». Per rivalutare una casa dopo nuove evidenze puoi usare «Aggiorna analisi AI» nello step 2.</p></div></div>`}
function fit(h){const p=state.profile;const values=[];const add=(key,score)=>{const w=Number(p.prefs[key]||0);if(w&&score!=null)values.push([w,score])};if(h.price&&p.budget)add('prezzo',clamp(5-((h.price-p.budget)/Math.max(p.budget,1))*10,1,5));if(h.address&&p.location)add('zona',h.address.toLowerCase().includes(p.location.toLowerCase())?5:null);if(h.visited){add('luminosita',h.visit.light);add('tranquillita',h.visit.quiet);add('spazi',h.visit.layout)};for(const c of p.custom){const value=h.visit.custom?.[c.id];if(value!=null)values.push([Number(c.weight||3),Number(value)])};const sum=values.reduce((a,[w,v])=>a+w*v,0),weights=values.reduce((a,[w])=>a+w,0);const all=Object.values(p.prefs).reduce((a,v)=>a+Number(v),0)+p.custom.reduce((a,c)=>a+c.weight,0);return {score:weights?Math.round(sum/weights/5*100):null,coverage:all?Math.round(weights/all*100):0}}
function areaName(id){return AREAS.find(a=>a[0]===id)?.[2]||'Altro'}
function statusText(h){return h.analysis?.mode==='ai'?'Analisi Mind The Gap · '+shortDate(h.analysis?.generatedAt):'Analisi AI non ancora eseguita. Nessun gap preimpostato: compila la casa e premi Analizza immobile' }
function overviewSection(h){const f=fit(h);const total=h.gaps.length,open=h.gaps.filter(g=>!g.closed).length;return `<div class="grid3 mb"><div class="metric"><span>Quanto fa per te</span><b>${f.score==null?'—':f.score+'/100'}</b><span>Basato sul ${f.coverage}% del peso dei criteri; gli altri non sono valutati</span></div><div class="metric"><span>Questioni ancora aperte</span><b>${open}</b><span>${total-open} chiuse da te (non necessariamente verificate)</span></div><div class="metric"><span>Documenti acquisiti</span><b>${h.docs.length}</b><span>Il numero non misura conformità o certezza</span></div></div><div class="info mb"><b>Stato dell'analisi</b> · ${esc(statusText(h))}. Nessun dato territoriale puntuale viene inventato: aria, rumore, OMI e rischi locali richiedono fonti geografiche effettive.</div><div class="grid2">${AREAS.map(([id,n,title,subtitle])=>{const evid=(h.analysis?.areas?.[id]?.evidences||[]);const count=h.gaps.filter(g=>g.area===id&&!g.closed).length;return `<div class="card area-card"><div class="area-head"><div><span class="eyebrow">${n} / ${esc(subtitle)}</span><h2>${esc(title)}</h2></div><span class="badge ${count?'medium':'ok'}">${count} aperte</span></div><div class="rule"></div><b class="smalltext">Evidenze disponibili</b>${evid.length?evid.slice(0,3).map(e=>`<div class="evidence"><div class="smalltext">${esc(e.fact)}</div><div class="tiny">${esc(e.source)} · ${esc(e.quality)}</div></div>`).join(''):'<p class="muted smalltext">Nessuna evidenza verificata. Puoi aggiungere informazioni e documenti.</p>'}<div class="rule"></div><div class="smalltext"><b>${count} verifiche da chiarire</b> · ${h.gaps.filter(g=>g.area===id&&!g.closed).sort((a,b)=>priorityWeight(b.priority)-priorityWeight(a.priority)).slice(0,3).map(g=>esc(g.title)).join(' · ')||'Nessuna aperta'}</div><button class="btn outline small mt" data-area="${id}">Apri le verifiche →</button></div>`}).join('')}</div><div class="btn-row mt"><button class="btn" id="openChecks">Approfondisci le verifiche</button><button class="btn outline" id="openVisit">${h.visited?'Modifica le sensazioni della visita':'Dopo la visita'}</button><button class="btn outline" id="refreshAnalysis">Aggiorna analisi AI</button></div>`}
function visitSection(h){const v=h.visit;return `<div class="grid2"><form class="card stack" id="visitForm"><div class="eyebrow">LA TUA ESPERIENZA</div><h2>Come ti sei sentito dentro questa casa?</h2><p class="muted smalltext">Queste valutazioni sono personali e specifiche di questo immobile. Non sono prove tecniche né caratteristiche deducibili dall'annuncio.</p><label class="check-row"><input id="visitDone" type="checkbox" ${h.visited?'checked':''}> Ho visitato la casa</label>${h.visited?`<div class="field"><label>Quando? (facoltativo)</label><input id="visitDate" class="input" type="date" value="${esc(h.visitedAt||'')}"></div>${[['feeling','Come ti sei sentito complessivamente?'],['light','Luminosità percepita'],['quiet','Tranquillità percepita'],['layout','Spazi e distribuzione percepiti']].map(([id,label])=>`<div class="range-row"><label>${label}</label><input type="range" min="1" max="5" value="${v[id]??3}" data-emotion="${id}"><b data-emotion-label="${id}">${v[id]??'—'}/5</b></div>`).join('')}${state.profile.custom.map(c=>`<div class="range-row"><label>${esc(c.name)}</label><input type="range" min="1" max="5" data-emotion-custom="${esc(c.id)}" value="${v.custom?.[c.id]??3}"><b>${v.custom?.[c.id]??'—'}/5</b></div>`).join('')}<div class="field"><label>Cosa ti è piaciuto e cosa ti ha lasciato dubbi?</label><textarea class="input" id="visitNote" rows="5" placeholder="Es. Mi piace la zona giorno, ma il rumore dalle finestre mi preoccupa">${esc(v.note)}</textarea></div>`:`<div class="notice">Puoi continuare la valutazione anche senza visita. Quando la farai potrai aggiungere le tue sensazioni.</div>`}<button class="btn" type="submit">Salva la visita e le impressioni</button></form><div class="card stack"><h2>Il tuo punto di vista conta</h2><p class="smalltext">Se la tranquillità per te vale 5/5 e hai percepito rumore, MTG può dare priorità ai controlli sul rumore. Ma una sensazione positiva non rende automaticamente sicura una casa.</p><h3>Indicazioni pratiche</h3><p class="smalltext">Se il rumore è importante: torna in orari diversi, ascolta nelle camere, apri e chiudi le finestre e, se il problema è determinante, valuta una misura acustica professionale.</p><p class="smalltext">Bussare sul muro non è una misura affidabile dell'isolamento acustico.</p><button class="btn outline" id="visitToGaps">Vai alle questioni aperte</button></div></div>`}
function priorityLabel(p){return ({critical:'Critica',high:'Alta',medium:'Media',low:'Da approfondire'})[p]||'Da valutare'}
function gapDocs(h,g){return (h.docs||[]).filter(d=>(g.documentIds||[]).includes(d.id))}
function areaEvidence(h,area){return h.analysis?.areas?.[area]?.evidences||[]}
function gapEvidence(h,g){return (g.manualEvidence||[])}
function specialization(g){const text=(g.title+' '+g.reason+' '+g.action).toLowerCase();if(/ipotec|provenienza|vincol|rogit|notaio|succession/.test(text))return {role:'Notaio',scope:'Aspetti giuridici e documentazione dell’acquisto'};if(/condomin|assemble|spese straordinar|amministrator/.test(text))return {role:'Amministratore di condominio o tecnico condominiale',scope:'Spese, delibere e parti comuni'};if(/energetic|ape|impiant|termic|isolament|acustic|rumore/.test(text))return {role:'Tecnico abilitato competente per materia',scope:'Valutazione tecnico-documentale o sopralluogo mirato'};if(/prezzo|mutuo|impost|budget|costi|finanzi/.test(text))return {role:'Consulente mutui o professionista fiscale, secondo il tema',scope:'Costi dell’operazione e sostenibilità finanziaria'};if(g.area==='quartiere')return {role:'Tecnico ambientale o consulente territoriale',scope:'Approfondimento puntuale con fonti e misurazioni appropriate'};return {role:'Architetto, geometra o ingegnere abilitato',scope:'Documenti edilizi, caratteristiche e verifiche dell’immobile'}}
function docRef(h,id){const d=(h.docs||[]).find(x=>x.id===id);return d?d.name+' · '+shortDate(d.addedAt):'Documento non più disponibile'}
function listGap(h,g){
 const opened=expandedGap===g.id;const docs=gapDocs(h,g);const statements=gapEvidence(h,g);const aiE=areaEvidence(h,g.area).filter(e=>e.gapId===g.id||e.gap_id===g.id);
 const summary=`${g.closed?'Chiusa dal buyer':priorityLabel(g.priority)} · ${g.evidenceLevel==='documented'?'Documenti collegati':g.evidenceLevel==='declared'?'Dichiarazione del buyer':'Da approfondire'}`;
 return `<div class="gap" id="gap_${esc(g.id)}"><div class="gap-header"><div><div class="gap-label">${esc(areaName(g.area))} · ${esc(g.source||'Origine da chiarire')}</div><div class="gap-title">${esc(g.title)}</div><div class="taglist mt"><span class="badge ${g.closed?'ok':g.priority==='critical'||g.priority==='high'?'high':g.priority==='medium'?'medium':'low'}">${esc(summary)}</span></div></div><button class="btn outline small" data-expand="${esc(g.id)}">${opened?'Riduci':'Apri fascicolo'}</button></div>${opened?`<div class="gap-details stack">
 <div class="gap-evidence-grid"><div><b class="smalltext">Cosa sappiamo</b><p class="smalltext">${esc(g.reason||'Non sono disponibili riscontri sufficienti.')}</p><p class="tiny">Fonte indicata: ${esc(g.source||'Non disponibile')}. Una dichiarazione non è una verifica.</p></div><div class="info"><b>Cosa chiedere / fare</b><p>${esc(g.action||'Chiedi chiarimenti.')}</p></div></div>
 <div class="gap-evidence-panel"><div class="area-head"><b>Evidenze collegate (${docs.length+statements.length+aiE.length})</b><span class="tiny">Fonti tracciate, non certificazioni</span></div>
 ${aiE.map(e=>`<div class="evidence"><b class="smalltext">${esc(e.fact)}</b><div class="tiny">${esc(e.source||'Fonte non indicata')} · ${esc(e.quality||'Qualità non valutata')}</div></div>`).join('')}
 ${docs.map(d=>`<div class="evidence"><b class="smalltext">📄 ${esc(d.name)}</b><div class="tiny">Caricato il ${shortDate(d.addedAt)} · ${esc(DOCS.find(x=>x[0]===d.kind)?.[1]||'Documento')} · La presenza non dimostra la validità</div></div>`).join('')}
 ${statements.map(e=>`<div class="evidence"><b class="smalltext">${esc(e.text)}</b><div class="tiny">${esc(e.sourceType==='buyer'?'Dichiarazione buyer':'Riscontro indicato dal buyer')} · ${shortDate(e.at)}</div></div>`).join('')}
 ${!(docs.length+statements.length+aiE.length)?'<p class="smalltext muted">Nessuna evidenza associata direttamente a questo gap.</p>':''}
 <div class="field mt"><label>Associa un documento già caricato</label><select class="input" data-doc-select="${esc(g.id)}"><option value="">Seleziona un documento</option>${(h.docs||[]).filter(d=>!docs.some(x=>x.id===d.id)).map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select></div>
 <div class="btn-row"><button class="btn outline small" data-link-doc="${esc(g.id)}">Collega documento</button><button class="btn ghost small" data-add-doc="${esc(g.id)}">Carica nuovo documento</button></div></div>
 <div class="field"><label>Risposta ricevuta o tua osservazione</label><textarea class="input" rows="3" data-gap-answer="${esc(g.id)}" placeholder="Es. L'agente ha risposto che...; indica sempre la fonte.">${esc(g.answer||'')}</textarea></div>
 <div class="field"><label>Da chi proviene la risposta?</label><select class="input" data-answer-source="${esc(g.id)}"><option value="buyer">Osservazione personale</option><option value="agent">Agente o venditore</option><option value="professional">Professionista</option><option value="other">Altra fonte</option></select></div>
 <div class="btn-row"><button class="btn outline small" data-save-answer="${esc(g.id)}">Salva riscontro</button><button class="btn outline small" data-close-gap="${esc(g.id)}">${g.closed?'Riapri':'Chiudi per mia scelta'}</button><button class="btn small" data-expert="${esc(g.id)}">Attiva specialista</button><button class="btn ghost small" data-copy-question="${esc(g.id)}">Copia domanda</button></div>
 <p class="tiny">Il buyer può chiudere un tema anche senza verifica. La chiusura resta esplicitamente distinta dal livello di evidenza disponibile.</p>
 <details><summary class="smalltext">Cronologia del fascicolo (${(g.history||[]).length})</summary>${(g.history||[]).length?g.history.map(t=>`<div class="timeline-event"><span>${shortDate(t.at)}</span><b>${esc(t.event)}</b> ${esc(t.detail||'')}</div>`).join(''):'<p class="tiny">Nessuna attività registrata.</p>'}</details></div>`:''}</div>`;
}

function checksSection(h){const open=h.gaps.filter(g=>!g.closed).length;return `<div class="section-top"><div><h2>Evidenze e verifiche</h2><p class="muted smalltext">${open} aperte · ${h.gaps.length-open} chiuse. Per ogni area trovi ciò che è documentato, cosa manca e la prossima azione.</p></div><div class="btn-row"><button class="btn outline small" id="exportQuestions">Esporta domande da fare</button><button class="btn outline small" id="goDocs">+ Documento</button></div></div>
 <div class="info mb"><b>Stato dell'analisi:</b> ${esc(statusText(h))}. Le evidenze di fonte AI sono distinte dai riscontri caricati e dalle risposte personali. Accedi per eseguire un'analisi Mind The Gap completa.</div>
 ${AREAS.map(([id,n,title])=>{const ae=areaEvidence(h,id), ag=h.gaps.filter(g=>g.area===id).sort((a,b)=>priorityWeight(b.priority)-priorityWeight(a.priority));return `<section class="card mb"><div class="area-head"><h2>${n} · ${esc(title)}</h2><span class="badge">${ag.filter(g=>!g.closed).length} aperte</span></div><div class="category-evidence"><b class="smalltext">Evidenze dell'area · ${ae.length} da analisi AI</b>${ae.length?ae.map(e=>`<div class="evidence"><div class="smalltext">${esc(e.fact||'')}</div><div class="tiny">Fonte: ${esc(e.source||'Non indicata')} · Qualità: ${esc(e.quality||'Non valutata')}</div></div>`).join(''):'<p class="smalltext muted">Nessuna evidenza di analisi AI ancora disponibile per quest’area.</p>'}<div class="tiny">Documenti caricati: ${(h.docs||[]).map(d=>esc(d.name)).join(', ')||'nessuno'}. Collegali ai singoli gap per registrare a cosa si riferiscono.</div></div>
 <div class="gap-summary"><b class="smalltext">Verifiche prioritarie</b><span class="tiny">${ag.length>3?'Prime 3 mostrate; espandi per le altre':''}</span></div>
 ${ag.slice(0,showAllGaps[id]?ag.length:3).map(g=>listGap(h,g)).join('')||'<p class="smalltext muted">Nessuna verifica presente. Non equivale a un controllo completo.</p>'}
 ${ag.length>3?`<button class="btn outline small mt" data-all-gaps="${id}">${showAllGaps[id]?'Mostra solo prioritarie':`Mostra tutte (${ag.length})`}</button>`:''}</section>`}).join('')}
 <div class="card stack"><h3>Aggiungi una tua domanda</h3><p class="smalltext muted">Puoi registrare un problema osservato alla visita, una preoccupazione o una verifica che MTG non ha suggerito.</p><div class="field"><label>Il tuo tema</label><textarea class="input" id="newTopic" placeholder="Es. Posso abbattere la parete tra cucina e soggiorno?"></textarea></div><button class="btn outline" id="addTopic">+ Aggiungi alle verifiche</button></div>`}

function priorityWeight(p){return ({critical:4,high:3,medium:2,low:1})[p]||0}
function decisionSection(h){const f=fit(h);const open=h.gaps.filter(g=>!g.closed);const ai=h.analysis;const pros=ai?.pros||[],cons=ai?.cons||[];return `<div class="grid2 mb"><div class="card"><div class="eyebrow">PREFERENZE</div><h2>Quanto fa per te</h2><div class="metric"><b>${f.score==null?'Non valutabile':f.score+'/100'}</b><span>Solo ${f.coverage}% del peso dei criteri risulta valutato. Le sensazioni vengono considerate solo dopo la visita.</span></div></div><div class="card"><div class="eyebrow">VERIFICHE</div><h2>Cosa resta aperto</h2><div class="metric"><b>${open.length}</b><span>Questioni da chiarire; la chiusura manuale non costituisce certificazione.</span></div></div></div><div class="proscons mb"><div class="card"><h3>Perché potrebbe fare per te</h3><ul>${pros.length?pros.map(x=>`<li>${esc(x)}</li>`).join(''):'<li>Salva le tue preferenze ed esegui l’analisi AI per ottenere motivazioni personalizzate.</li>'}</ul></div><div class="card"><h3>Perché potresti non sceglierla</h3><ul>${cons.length?cons.map(x=>`<li>${esc(x)}</li>`).join(''):`<li>Ci sono ${open.length} verifiche aperte. Non sono necessariamente problemi accertati.</li>`}</ul></div></div><div class="card mb"><div class="area-head"><div><h2>Report approfondito della casa</h2><p class="smalltext muted">Annuncio, storico datato, preferenze, giudizi dopo la visita, documenti, evidenze, gap, pro e contro, limiti dell'analisi e decisione.</p></div><b style="font-size:28px">15 €</b></div><div class="btn-row"><button class="btn" id="reportIntent">${h.reportUnlocked?'Apri report ed esporta PDF':'Simula acquisto report · 15 €'}</button><span class="tiny">Nessun pagamento reale nell'MVP.</span></div></div><form class="card stack" id="decisionForm"><h2>Qual è la tua decisione oggi?</h2><div class="field"><label>Stato</label><select class="input" id="decisionChoice"><option value="pending" ${h.decision.choice==='pending'?'selected':''}>Voglio ancora approfondire</option><option value="offer" ${h.decision.choice==='offer'?'selected':''}>Sto valutando un'offerta</option><option value="offered" ${h.decision.choice==='offered'?'selected':''}>Ho presentato un'offerta</option><option value="no" ${h.decision.choice==='no'?'selected':''}>Ho deciso di non procedere</option></select></div><div class="field"><label>Motivo della rinuncia, se non procedi</label><select class="input" id="decisionReason"><option value="">Seleziona il motivo</option>${[['prezzo','Prezzo e costi'],['tecnico','Questioni tecniche o documentali'],['emotivo','Sensazioni durante la visita'],['preferenze','Non risponde alle mie esigenze'],['altra','Ho trovato un’alternativa'],['altro','Altro']].map(([v,n])=>`<option value="${v}" ${h.decision.reason===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Note (facoltative)</label><textarea class="input" id="decisionNote" rows="3">${esc(h.decision.note)}</textarea></div><button class="btn" type="submit">Registra la mia decisione</button></form>`}
function comparePage(){if(state.homes.length<2)return `${pageTop('Confronta le case','Aggiungi almeno due immobili per costruire il confronto.')}<div class="card"><button class="btn" id="compareAdd">+ Aggiungi un altro immobile</button></div>`;return `${pageTop('Confronta le tue case','Preferenze condivise, impressioni specifiche per immobile e verifiche tenute separate.')}<div class="card mb"><div class="info">Il confronto di base è consultabile; il report comparativo approfondito è disponibile tramite intenzione d'acquisto simulata. Nessun pagamento reale.</div><div style="overflow:auto;margin-top:14px"><table class="comparison"><thead><tr><th>Criterio</th>${state.homes.map(h=>`<th>${esc(homeTitle(h))}</th>`).join('')}</tr></thead><tbody>${[['Prezzo',h=>euros(h.price)],['Superficie',h=>h.sqm?`${esc(h.sqm)} m²`:'—'],['Compatibilità',h=>fit(h).score==null?'Non valutabile':`${fit(h).score}/100 (${fit(h).coverage}% criteri)`],['Visita',h=>h.visited?'Effettuata':'Da fare'],['Sensazione complessiva',h=>h.visited&&h.visit.feeling?`${h.visit.feeling}/5`:'Non valutata'],['Questioni aperte',h=>String(h.gaps.filter(g=>!g.closed).length)],['Documenti',h=>String(h.docs.length)],['Decisione',h=>({pending:'Da valutare',offer:'Valuto offerta',offered:'Offerta presentata',no:'Scartata'})[h.decision.choice]||'—']].map(([name,fn])=>`<tr><td>${name}</td>${state.homes.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="card"><div class="area-head"><div><h2>Report comparativo</h2><p class="muted smalltext">Pro e contro per ciascuna casa, criteri condivisi, gap e differenze nelle evidenze.</p></div><b style="font-size:25px">29 €</b></div><button class="btn mt" id="compareIntent">${state.compareUnlocked?'Esporta confronto':'Simula acquisto confronto · 29 €'}</button><p class="tiny">Pacchetto e prezzo da validare. Nessun addebito reale.</p></div>`}
function bind(){
 $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#logo').onclick=()=>navigate('research');$('#accountBtn').onclick=accountDialog;
 $('#openHomes')?.addEventListener('click',()=>navigate('homes'));$('#startHome')?.addEventListener('click',createHome);$('#newHome')?.addEventListener('click',createHome);$('#firstHome')?.addEventListener('click',createHome);$('#compareAdd')?.addEventListener('click',createHome);
 $$('[data-open]').forEach(b=>b.onclick=()=>{section='overview';navigate('property',b.dataset.open)});
 $$('[data-remove]').forEach(b=>b.onclick=()=>{if(!confirm('Eliminare questa valutazione? L’operazione non è reversibile.'))return;state.homes=state.homes.filter(h=>h.id!==b.dataset.remove);log('home_deleted');persist();render()});
 const pform=$('#profileForm');if(pform){pform.onsubmit=e=>{e.preventDefault();const p=state.profile;p.budget=Number($('#pBudget').value)||0;p.location=$('#pLocation').value.trim();p.purpose=$('#pPurpose').value;p.prefs=Object.fromEntries(PREFS.map(([id])=>[id,Number($(`[data-pref="${id}"]`).value)]));p.custom=p.custom.map(c=>({...c,weight:Number($(`[data-pref="${c.id}"]`).value)}));log('preferences_saved');persist();toast('Preferenze salvate');render()};$('#addPref').onclick=()=>{const n=$('#customPref').value.trim();if(!n)return;state.profile.custom.push({id:'custom_'+uid().replaceAll('-','').slice(0,12),name:n,weight:3});log('criterion_added');persist();render()};$('#startHome').onclick=createHome;$$('[data-pref]').forEach(el=>el.oninput=()=>{$(`[data-weight-label="${el.dataset.pref}"]`).textContent=el.value+'/5'})}
 if(view!=='property'){const comp=$('#compareIntent');if(comp)comp.onclick=()=>{if(state.compareUnlocked)return exportPrintCompare();state.compareUnlocked=true;log('payment_intent',{product:'comparison_29',amount:29,realPayment:false});persist();toast('Interesse registrato · nessun addebito');render()};return}
 const h=H();if(!h)return;
 $('#addNext').onclick=createHome;$('#editProfile').onclick=()=>navigate('research');$('#hStage').onchange=e=>{h.stage=e.target.value;log('stage_changed',{homeId:h.id,stage:h.stage});h.updatedAt=now();persist();render()};$('#hVisited').onchange=e=>{h.visited=e.target.value==='yes';if(h.visited&&h.stage==='online')h.stage='visited';h.updatedAt=now();log('visit_changed',{homeId:h.id,visited:h.visited});persist();render()};$$('[data-section]').forEach(b=>b.onclick=()=>setSection(b.dataset.section));
 function collectPropertyForm(){if(!$('#homeForm'))return;Object.assign(h,{name:$('#hName').value.trim()||'Immobile',description:$('#hDescription').value.trim(),address:$('#hAddress').value.trim(),link:$('#hLink').value.trim(),price:Number($('#hPrice').value)||null,sqm:Number($('#hSqm').value)||null,floor:$('#hFloor').value.trim(),energy:$('#hEnergy').value,condition:$('#hCondition').value,condoCosts:Number($('#hCondo').value)||null,updatedAt:now()});if(/^Nuovo immobile ·/.test(h.name))h.name=suggestedHouseName(h.description,h.createdAt);log('property_saved',{homeId:h.id});persist()}
 $('#homeForm')?.addEventListener('submit',async e=>{e.preventDefault();collectPropertyForm();await runAnalysis(h,{advance:true})});
 $('#uploadDoc')?.addEventListener('click',async()=>{collectPropertyForm();const file=$('#docFile').files?.[0];if(!file)return toast('Seleziona prima un PDF o un TXT');try{busy=true;toast('Lettura del documento…');const content=await readFile(file);const newDoc={id:uid(),name:file.name,kind:$('#docKind').value,text:content,addedAt:now(),size:file.size};h.docs.push(newDoc);if(pendingGapDoc){const g=h.gaps.find(g=>g.id===pendingGapDoc);if(g){g.documentIds=g.documentIds||[];g.documentIds.push(newDoc.id);g.evidenceLevel='documented';g.history=g.history||[];g.history.push({at:now(),event:'Documento caricato e associato',detail:newDoc.name})}pendingGapDoc='';}h.updatedAt=now();log('document_uploaded',{homeId:h.id,kind:$('#docKind').value,size:file.size});persist();render();toast('Documento aggiunto. Aggiorna l’analisi per utilizzarlo.')}catch(e){toast(e.message)}finally{busy=false}});
 $$('[data-del-doc]').forEach(b=>b.onclick=()=>{if(!confirm('Rimuovere questo documento e il suo testo estratto?'))return;h.docs=h.docs.filter(d=>d.id!==b.dataset.delDoc);for(const g of h.gaps){if((g.documentIds||[]).includes(b.dataset.delDoc)){g.documentIds=g.documentIds.filter(id=>id!==b.dataset.delDoc);g.history=g.history||[];g.history.push({at:now(),event:'Documento rimosso dal fascicolo'});g.evidenceLevel=g.documentIds.length?'documented':g.answer?'declared':'missing'}}persist();render()});
 $('#refreshAnalysis')?.addEventListener('click',()=>runAnalysis(h));
 $$('[data-area]').forEach(b=>b.onclick=()=>{expandedGap=h.gaps.find(g=>g.area===b.dataset.area&&!g.closed)?.id||'';setSection('checks')});$('#openChecks')?.addEventListener('click',()=>setSection('checks'));$('#openVisit')?.addEventListener('click',()=>setSection('visit'));
 $('#visitDone')?.addEventListener('change',e=>{h.visited=e.target.checked;if(h.visited&&h.stage==='online')h.stage='visited';persist();render()});
 $$('[data-emotion]').forEach(e=>e.oninput=()=>{const l=$(`[data-emotion-label="${e.dataset.emotion}"]`);if(l)l.textContent=e.value+'/5'});
 $('#visitForm')?.addEventListener('submit',e=>{e.preventDefault();const visited=$('#visitDone')?.checked||false;h.visited=visited;if(visited){h.stage=h.stage==='online'?'visited':h.stage;h.visitedAt=$('#visitDate')?.value||h.visitedAt||new Date().toISOString().slice(0,10);for(const k of ['feeling','light','quiet','layout'])h.visit[k]=Number($(`[data-emotion="${k}"]`)?.value||3);h.visit.custom=Object.fromEntries($$('[data-emotion-custom]').map(el=>[el.dataset.emotionCustom,Number(el.value)]));h.visit.note=$('#visitNote')?.value.trim()||'';const g=h.gaps.find(x=>x.id==='quartiere_rumore');if(g){g.priority=Number(state.profile.prefs.tranquillita)>=4&&Number(h.visit.quiet)<=2?'high':g.priority;g.reason=Number(h.visit.quiet)<=2?'Hai percepito rumore durante la visita e la tranquillità è un criterio personale.':g.reason;}}h.updatedAt=now();log('visit_saved',{homeId:h.id,visited});persist();toast('Impressioni salvate');render()});$('#visitToGaps')?.addEventListener('click',()=>setSection('checks'));
 $$('[data-expand]').forEach(b=>b.onclick=()=>{expandedGap=expandedGap===b.dataset.expand?'':b.dataset.expand;render()});
 $$('[data-all-gaps]').forEach(b=>b.onclick=()=>{showAllGaps[b.dataset.allGaps]=!showAllGaps[b.dataset.allGaps];render()});
 $$('[data-add-doc]').forEach(b=>b.onclick=()=>{pendingGapDoc=b.dataset.addDoc;section='details';render();toast('Carica un documento: sarà associato a questa verifica.');});
 $$('[data-link-doc]').forEach(b=>b.onclick=()=>{const g=h.gaps.find(x=>x.id===b.dataset.linkDoc);const documentId=$(`[data-doc-select="${g.id}"]`)?.value;if(!documentId)return toast('Seleziona prima un documento');g.documentIds=g.documentIds||[];if(!g.documentIds.includes(documentId))g.documentIds.push(documentId);g.evidenceLevel='documented';g.history=g.history||[];g.history.push({at:now(),event:'Documento associato',detail:docRef(h,documentId)});log('gap_document_linked',{homeId:h.id,gapId:g.id});persist();render();toast('Documento collegato. Non equivale a una verifica professionale')});
 $$('[data-save-answer]').forEach(b=>b.onclick=()=>{const g=h.gaps.find(x=>x.id===b.dataset.saveAnswer);if(!g)return;const answer=$(`[data-gap-answer="${g.id}"]`).value.trim();g.answer=answer;const sourceType=$(`[data-answer-source="${g.id}"]`)?.value||'buyer';g.manualEvidence=g.manualEvidence||[];if(answer&&(!g.manualEvidence.length||g.manualEvidence[g.manualEvidence.length-1].text!==answer)){g.manualEvidence.push({id:uid(),text:answer,at:now(),sourceType})}g.evidenceLevel=(g.documentIds||[]).length?'documented':answer?'declared':'missing';g.history=g.history||[];g.history.push({at:now(),event:'Riscontro salvato',detail:(sourceType+': '+answer).slice(0,250)});h.updatedAt=now();log('gap_answer',{homeId:h.id,gapId:g.id});persist();toast('Risposta salvata. È una dichiarazione, non una verifica documentale');render()});
 $$('[data-close-gap]').forEach(b=>b.onclick=()=>{const g=h.gaps.find(x=>x.id===b.dataset.closeGap);g.closed=!g.closed;g.history.push({at:now(),event:g.closed?'Chiusa dal buyer':'Riaperta dal buyer'});h.updatedAt=now();log('gap_status',{homeId:h.id,gapId:g.id,closed:g.closed});persist();render()});
 $$('[data-copy-question]').forEach(b=>b.onclick=async()=>{const g=h.gaps.find(x=>x.id===b.dataset.copyQuestion);try{await navigator.clipboard.writeText(g.action);toast('Domanda copiata')}catch{toast('Copia non disponibile: seleziona il testo manualmente')}});
 $$('[data-expert]').forEach(b=>b.onclick=()=>{expertGap=b.dataset.expert;showExpert(h)});
 $('#goDocs')?.addEventListener('click',()=>setSection('details'));$('#exportQuestions')?.addEventListener('click',()=>exportExcelCSV(h));
 $('#addTopic')?.addEventListener('click',async()=>{const q=$('#newTopic').value.trim();if(q.length<8)return toast('Descrivi il tema in almeno 8 caratteri.');if(h.gaps.some(g=>g.title.toLowerCase()===q.toLowerCase()))return toast('Il tema è già presente');const custom={id:'buyer_'+uid().replaceAll('-','').slice(0,12),area:'immobile',title:q,priority:'medium',reason:'Tema aggiunto dal buyer; non ancora verificato.',action:'Raccogli informazioni o richiedi un approfondimento mirato.',source:'Tema inserito dal buyer',stage:'any',closed:false,answer:'',evidenceLevel:'missing',history:[{at:now(),event:'Tema creato dal buyer'}]};h.gaps.push(custom);h.updatedAt=now();log('custom_topic_added',{homeId:h.id});persist();render();toast('Tema aggiunto. Puoi farlo analizzare da Mind The Gap.');if(supa&&session){try{const r=await ai('topic',{topic:q,property:aiProperty(h),buyerProfile:aiProfile(),existingGaps:h.gaps.map(g=>({id:g.id,title:g.title,area:g.area}))});if(r?.topic){Object.assign(custom,{area:AREAS.some(a=>a[0]===r.topic.area)?r.topic.area:'immobile',priority:r.topic.priority||'medium',reason:r.topic.reason||custom.reason,action:r.topic.action||custom.action});if(r.topic.match_existing){const existing=h.gaps.find(g=>g.id===r.topic.match_existing&&g.id!==custom.id);if(existing){existing.history.push({at:now(),event:'Tema buyer collegato',detail:q});h.gaps=h.gaps.filter(g=>g.id!==custom.id)}}persist();render()}}catch(e){toast('Tema salvato; approfondimento AI non disponibile: '+e.message)}}});
 $('#reportIntent')?.addEventListener('click',()=>{if(!h.reportUnlocked){h.reportUnlocked=true;state.intents.push({id:uid(),at:now(),type:'report',amount:15,homeId:h.id,realPayment:false});log('payment_intent',{product:'report_15',homeId:h.id,realPayment:false});persist();toast('Acquisto simulato · Nessun addebito');render()}else exportPrintReport(h)});
 $('#decisionForm')?.addEventListener('submit',e=>{e.preventDefault();const choice=$('#decisionChoice').value,reason=$('#decisionReason').value;if(choice==='no'&&!reason)return toast('Indica il motivo per cui non procedi');h.decision={choice,reason:choice==='no'?reason:'',note:$('#decisionNote').value.trim(),date:now()};if(choice==='offered')h.stage='offered';if(choice==='offer')h.stage='offer';if(choice==='no')h.stage='discarded';h.updatedAt=now();log('decision_saved',{homeId:h.id,choice,reason:h.decision.reason});persist();toast('Decisione salvata');render()});
}
function aiProfile(){const p=state.profile;return {budget:p.budget,location:p.location,purpose:p.purpose,weights:p.prefs,custom:p.custom}}
function aiProperty(h){return {description:h.description,link:h.link,area:h.address,price:h.price,sqm:h.sqm,floor:h.floor,energy:h.energy,condition:h.condition,condoCosts:h.condoCosts}}
async function ai(operation,params){if(!supa||!session){accountDialog();throw Error('Accedi per utilizzare l’analisi Mind The Gap')}const {data,error}=await supa.functions.invoke('mtg-ai',{body:{operation,...params}});if(error){let msg=error.message;try{const e=await error.context.json();msg=e.error||msg}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data}
async function runAnalysis(h,{advance=false}={}){
 if(busy)return false;
 if(!h.description.trim()&&!h.docs.length){toast('Aggiungi la descrizione dell’annuncio o almeno un documento per iniziare.');return false}
 if(!supa||!session){accountDialog();toast('Immobile salvato. Accedi a Supabase, poi premi Analizza immobile.');return false}
 busy=true;const action=$('#analyzeProperty');if(action){action.disabled=true;action.textContent='Analisi in corso…'}
 toast('Analizzo l’immobile e preparo verifiche specifiche, senza duplicati…');
 try{
  cleanupLegacyGaps(h);
  const data=await ai('workspace_analysis',{property:aiProperty(h),buyerProfile:aiProfile(),visitStatus:h.visited?'visited':'not_visited',visitNotes:h.visit,documents:h.docs.map(d=>({name:d.name,kind:d.kind,text:d.text})),existingGaps:h.gaps.map(g=>({id:g.id,title:g.title,area:g.area,closed:g.closed,answer:g.answer,source:g.source}))});
  if(!data?.analysis?.areas||!Array.isArray(data.analysis.gaps))throw Error('La funzione Mind The Gap non ha restituito le quattro sezioni previste');
  const generated=distinctGaps(data.analysis.gaps).slice(0,12);
  const preserved=h.gaps.filter(g=>!isLegacyPreset(g));
  const merged=[];
  for(const g of generated){
   const existing=preserved.find(x=>sameGap(x,g));
   if(existing){
    // Do not overwrite buyer-authored topics or their record of what was discussed.
    const isBuyer=String(existing.id).startsWith('buyer_');
    merged.push({...existing,area:g.area,title:isBuyer?existing.title:g.title,priority:g.priority,reason:g.reason,action:g.action,source:g.source,stage:g.stage,origin:isBuyer?'buyer':'ai',history:existing.history||[]});
   }else merged.push({...g,origin:'ai',closed:false,answer:'',evidenceLevel:'missing',documentIds:[],manualEvidence:[],history:[{at:now(),event:'Suggerita dall’analisi AI'}]});
  }
  // Keep old gap records only when the buyer interacted with them; no stale AI suggestions.
  for(const old of preserved){if(merged.some(x=>sameGap(x,old)))continue;if(String(old.id).startsWith('buyer_')||old.closed||old.answer||(old.documentIds||[]).length||(old.manualEvidence||[]).length){merged.push({...old,history:[...(old.history||[]),{at:now(),event:'Conservata dallo storico della precedente analisi'}]})}}
  h.gaps=distinctGaps(merged);
  h.analysis={...data.analysis,gaps:h.gaps.map(g=>({id:g.id,area:g.area,title:g.title,priority:g.priority,reason:g.reason,action:g.action,source:g.source,stage:g.stage})),mode:'ai',generatedAt:now()};
  h.updatedAt=now();log('analysis_completed',{homeId:h.id,gapCount:generated.length});persist();
  if(advance)section='overview';render();if(advance)scrollTo(0,0);
  toast(`${generated.length} verifiche distinte individuate. ${advance?'Ora sei nello step 2 · Valutazione.':'Analisi aggiornata.'}`);
  return true;
 }catch(e){toast('Analisi non riuscita: '+e.message);return false}
 finally{busy=false;const a=$('#analyzeProperty');if(a){a.disabled=false;a.textContent=h.analysis?'Aggiorna analisi immobile →':'Analizza immobile →'}}
}
async function readFile(file){if(file.size>8*1024*1024)throw Error('File troppo grande: limite 8 MB');if(/\.txt$/i.test(file.name))return (await file.text()).slice(0,35000);if(!/\.pdf$/i.test(file.name))throw Error('Carica PDF testuale o TXT');const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let t='';for(let i=1;i<=Math.min(20,pdf.numPages);i++){const page=await pdf.getPage(i);const content=await page.getTextContent();t+=`\n[pagina ${i}] `+content.items.map(x=>x.str||'').join(' ');if(t.length>35000)break}if(t.trim().length<50)throw Error('PDF scansito o senza testo leggibile. Per ora non è disponibile OCR.');return t.slice(0,35000)}
function showExpert(h){const g=h.gaps.find(g=>g.id===expertGap);if(!g)return;const rec=specialization(g);modal(`<div class="stack"><div class="eyebrow">SPECIALISTA · RICHIESTA DEMO</div><h2>${esc(g.title)}</h2><div class="info"><b>Professione indicata</b><p>${esc(rec.role)}</p><p class="tiny">${esc(rec.scope)}. Il professionista effettivo e le competenze saranno confermati prima dell'incarico.</p></div><div><b class="smalltext">Perimetro iniziale</b><p class="smalltext">${esc(g.action||g.title)}</p></div><div class="field"><label>Come vuoi approfondire?</label><select class="input" id="expertService"><option value="video">Videoconsulenza · prezzo ipotetico 200 €</option><option value="inspection">Sopralluogo · prezzo ipotetico 500 €</option></select></div><div class="field"><label>Ulteriori aspetti richiesti (da preventivare)</label><textarea class="input" id="expertExtra" rows="3" placeholder="Es. Voglio verificare anche un altro dubbio..."></textarea></div><div class="info"><b>Report professionale incluso nel servizio</b><p class="smalltext">Se il servizio verrà realmente erogato, il report sui temi concordati è compreso nel prezzo della prestazione, indipendentemente dall'acquisto del dossier MTG.</p></div><div class="notice">Non sono ancora disponibili professionisti da scegliere o prenotazioni reali. Nessun pagamento sarà effettuato; la richiesta registra solo un'intenzione.</div><div class="btn-row"><button class="btn" id="expertSubmit">Simula richiesta</button><button class="btn outline" data-close>Chiudi</button></div></div>`);$('#expertSubmit').onclick=()=>{const service=$('#expertService').value,extra=$('#expertExtra').value.trim();h.expertRequests.push({at:now(),gapId:g.id,scope:g.title,service,extra,profession:rec.role,simulation:true});g.history=g.history||[];g.history.push({at:now(),event:'Interesse specialista (simulato)',detail:rec.role+' · '+(service==='video'?'Videocall':'Sopralluogo')});log('expert_interest',{homeId:h.id,gapId:g.id,service,realPayment:false});persist();$('#modal').close();toast('Interesse registrato: nessun incarico o pagamento reale');render()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}

function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}
function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportExcelCSV(h){const rows=[['Area','Priorità','Questione','Prossimo passo','Stato','Risposta buyer','Fonte'],...h.gaps.map(g=>[areaName(g.area),priorityLabel(g.priority),g.title,g.action,g.closed?'Chiusa da te':'Aperta',g.answer,g.source])];download('MTG_Domande_'+slug(h.name)+'.csv','text/csv;charset=utf-8','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'));log('questions_exported',{homeId:h.id});persist()}
function slug(t){return String(t||'casa').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'_').slice(0,48)}
function printWindow(html){const w=window.open('','_blank');if(!w){toast('Consenti i popup per esportare in PDF');return}w.document.write(`<!doctype html><html lang="it"><head><meta charset="utf-8"><title>MTG Report</title><style>body{font:12px/1.5 Arial,sans-serif;color:#172b40;max-width:840px;margin:32px auto}h1{color:#0f3460;font-size:26px}h2{border-bottom:1px solid #ddd;margin-top:26px;padding-bottom:5px}h3{font-size:14px;margin-bottom:3px}section{page-break-inside:avoid;margin-bottom:14px}.label{font-size:11px;color:#66778b}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;text-align:left;padding:7px}p{margin:5px 0}small{color:#607588}</style></head><body>${html}<script>window.onload=()=>{setTimeout(()=>window.print(),400)}<\/script></body></html>`);w.document.close()}
function exportPrintReport(h){const f=fit(h);const page=`<h1>mindthegap. · Dossier immobile</h1><small>Emesso il ${new Date().toLocaleString('it-IT')} · Snapshot, non certificazione</small><h2>${esc(homeTitle(h))}</h2><p>${esc(h.address)} · ${euros(h.price)} · ${h.sqm||'—'} m²</p><h2>Annuncio originale inserito</h2><p>${esc(h.description)}</p><h2>Preferenze della ricerca</h2><p>Budget ${euros(state.profile.budget)} · Zona ${esc(state.profile.location)} · ${PREFS.map(([k,n])=>`${n}: ${state.profile.prefs[k]}/5`).join(' · ')}${state.profile.custom.map(x=>` · ${esc(x.name)}: ${x.weight}/5`).join('')}</p><h2>Compatibilità e limiti</h2><p>Compatibilità ${f.score==null?'non valutabile':f.score+'/100'} · Criteri valutati ${f.coverage}% del peso complessivo. Il punteggio non misura sicurezza o conformità.</p><h2>Visita e sensazioni</h2><p>${h.visited?`Visita effettuata il ${esc(h.visitedAt||'giorno non indicato')}. Sensazione ${h.visit.feeling??'—'}/5; luce ${h.visit.light??'—'}/5; tranquillità ${h.visit.quiet??'—'}/5; spazi ${h.visit.layout??'—'}/5. ${esc(h.visit.note)}`:'Non ancora visitata'}</p><h2>Evidenze e documenti inseriti</h2>${h.docs.map(d=>`<p>• ${esc(d.name)} (${esc(d.kind)}), aggiunto il ${shortDate(d.addedAt)} — testo ${d.text?.length?'estratto':'non disponibile'}</p>`).join('')||'<p>Nessun documento caricato</p>'}${AREAS.map(([a,,n])=>`<h2>${esc(n)}</h2>${(h.analysis?.areas?.[a]?.evidences||[]).map(x=>`<section><b>${esc(x.fact)}</b><p class="label">${esc(x.source)} · ${esc(x.quality)}</p></section>`).join('')||'<p>Nessuna evidenza da analisi AI disponibile.</p>'}${h.gaps.filter(g=>g.area===a).map(g=>`<section><h3>${esc(g.title)} · ${g.closed?'Chiusa dal buyer':'Aperta'}</h3><p>${esc(g.reason)}</p><p><b>Cosa fare:</b> ${esc(g.action)}</p><p><b>Risposta buyer:</b> ${esc(g.answer||'Non disponibile')}</p><p><b>Documenti associati:</b> ${(g.documentIds||[]).map(id=>esc(docRef(h,id))).join('; ')||'Nessuno'}</p><p><b>Riscontri datati:</b> ${(g.manualEvidence||[]).map(e=>shortDate(e.at)+' '+esc(e.sourceType)+': '+esc(e.text)).join(' · ')||'Nessuno'}</p><p class="label">${esc(g.source)} · ${esc(g.history?.map(x=>shortDate(x.at)+' '+x.event).join('; ')||'')}</p></section>`).join('')}`).join('')}<h2>Perché comprarla / perché non comprarla</h2><b>Pro</b><ul>${(h.analysis?.pros||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non effettuata</li>'}</ul><b>Contro</b><ul>${(h.analysis?.cons||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non effettuata</li>'}</ul><h2>Decisione</h2><p>${esc(h.decision.choice)} · ${esc(h.decision.reason||'')} · ${esc(h.decision.note||'')} · ${shortDate(h.decision.date)}</p><p><small>Informazioni riportate a scopo decisionale preliminare. Un documento caricato non dimostra conformità. Le informazioni territoriali non verificate e le prestazioni professionali simulate non hanno valore di accertamento.</small></p>`;printWindow(page);log('report_print',{homeId:h.id});persist()}
function exportPrintCompare(){const cells=state.homes.map(h=>({h,f:fit(h)}));printWindow(`<h1>mindthegap. · Confronto immobili</h1><small>Generato il ${new Date().toLocaleString('it-IT')}; valutazioni indicative, informazioni non certificate</small><table><tr><th>Immobile</th><th>Prezzo</th><th>Compatibilità</th><th>Copertura criteri</th><th>Gap aperti</th></tr>${cells.map(({h,f})=>`<tr><td>${esc(homeTitle(h))}</td><td>${euros(h.price)}</td><td>${f.score??'—'}/100</td><td>${f.coverage}%</td><td>${h.gaps.filter(g=>!g.closed).length}</td></tr>`).join('')}</table>${cells.map(({h})=>`<h2>${esc(homeTitle(h))}</h2><b>Perché potrebbe fare per te</b><ul>${(h.analysis?.pros||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non disponibile</li>'}</ul><b>Perché potrebbe non fare per te</b><ul>${(h.analysis?.cons||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Analisi non disponibile</li>'}</ul>`).join('')}`);log('comparison_print');persist()}
function accountDialog(){if(session){modal(`<h2>Il mio account</h2><p>${esc(session.user.email||'Accesso Supabase')}</p><p class="muted smalltext">${cloudReady?'Dati sincronizzati con account':'Salvataggio locale nella sessione del browser.'}</p><div class="btn-row"><button class="btn outline" id="logout">Esci</button><button class="btn ghost" data-close>Chiudi</button></div>`);$('#logout').onclick=async()=>{await supa.auth.signOut();session=null;cloudReady=false;$('#modal').close();render()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());return}modal(`<h2>Accedi a MTG</h2><p class="smalltext muted">Per usare Mind The Gap e sincronizzare le valutazioni, accedi tramite email. Il collegamento Supabase resta quello del progetto esistente.</p><form id="loginForm" class="stack"><div class="field"><label>Email</label><input class="input" id="loginEmail" type="email" required placeholder="nome@email.it"></div><button class="btn" type="submit">Invia link di accesso</button></form><p class="tiny">Il login richiede configurazione Supabase Auth e Redirect URLs per il sito GitHub Pages.</p><button class="btn ghost mt" data-close>Chiudi</button>`);$('#loginForm').onsubmit=async e=>{e.preventDefault();if(!supa)return toast('Configura web/config.js con Supabase URL e publishable key');const email=$('#loginEmail').value.trim();const {error}=await supa.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname}});toast(error?'Login non riuscito: '+error.message:'Controlla la tua email per il link di accesso');if(!error)$('#modal').close()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
async function loadCloud(){if(!supa||!session)return;const {data,error}=await supa.from('mtg_workspaces').select('data').eq('user_id',session.user.id).maybeSingle();if(error){cloudReady=false;cloudError=error.message;updateSyncLabel();return}cloudReady=true;cloudError='';if(data?.data?.version){if(!state.homes.length || confirm('Esiste un workspace salvato su Supabase. Vuoi caricarlo? (La versione locale corrente sarà sostituita.)')){state={...fresh(),...data.data};localStorage.setItem(KEY,JSON.stringify(state))}}else{await saveCloud()}render()}
async function init(){render();if(!CONFIG.supabaseUrl||!CONFIG.supabasePublishableKey)return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');supa=createClient(CONFIG.supabaseUrl,CONFIG.supabasePublishableKey);const {data}=await supa.auth.getSession();session=data.session;supa.auth.onAuthStateChange((_event,s)=>{const was=session?.user?.id;session=s;if(s&&s.user.id!==was)loadCloud();else if(!s){cloudReady=false;render()}else updateSyncLabel()});if(session)await loadCloud();else render()}catch(e){cloudError=e.message;render()}}
init();
